SELECT order_cohort, stddev_shipping_fee FROM (SELECT CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, ROUND(STDDEV(shipping_fee), 2) AS stddev_shipping_fee FROM orders WHERE status = 'RETURNED' GROUP BY CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END) AS s WHERE stddev_shipping_fee >= 77 ORDER BY order_cohort DESC;
